class Solution:
    def unhappyFriends(self, n: int, preferences, pairs):
        pair_map = {}
        for x, y in pairs:
            pair_map[x] = y
            pair_map[y] = x

        unhappy_friends = set()

        for x in range(n):
            y = pair_map[x]
            for u in range(n):
                if x == u:
                    continue
                v = pair_map[u]
                if self.prefers(preferences, x, u, y) and self.prefers(preferences, u, x, v):
                    unhappy_friends.add(x)
                    unhappy_friends.add(u)

        return len(unhappy_friends)

    def prefers(self, preferences, x, u, y):
        u_index = -1
        y_index = -1
        for i, friend in enumerate(preferences[x]):
            if friend == u:
                u_index = i
            if friend == y:
                y_index = i
        if u_index == -1 or y_index == -1:
            return False
        return u_index < y_index

