    def minSwaps(self, grid: list[list[int]]) -> int:
        n = len(grid)
        trailing_zeros = []
        for row in grid:
            count = 0
            for i in range(n - 1, -1, -1):
                if row[i] == 0:
                    count += 1
                else:
                    break
            trailing_zeros.append(count)

        swaps = 0
        indices = list(range(n))
        for i in range(n):
            required_zeros = n - 1 - i
            found = False
            for j in range(i, n):
                if trailing_zeros[indices[j]] >= required_zeros:
                    found = True
                    for k in range(j, i, -1):
                        indices[k], indices[k - 1] = indices[k - 1], indices[k]
                        swaps += 1
                    break
            if not found:
                return -1
        return swaps
